def parse_hhmm(text: str) -> int:
    """Return the number of minutes in an ``"H:MM"`` duration."""
    parts = text.split(":")
    if len(parts) != 2:
        raise ValueError(f"Invalid time format: {text}")
    try:
        hours = int(parts[0])
        minutes = int(parts[1])
    except ValueError:
        raise ValueError(f"Invalid time format: {text}")
    if minutes >= 60:
        raise ValueError(f"Minutes must be below 60, got: {minutes}")
    return hours * 60 + minutes

